/**
 * @edgway/sdk: the admin API's typed client, TanStack Query options and zod
 * schemas, generated by @hey-api/openapi-ts from apps/admin/openapi.json
 * (src/generated, never edited by hand). This file only re-exports them and
 * adds a constructor for a client bound to one admin.
 */

import {
  type Client,
  createClient,
  createConfig,
} from "./generated/client/index.js";
import { client } from "./generated/client.gen.js";

export * from "./generated/@tanstack/react-query.gen.js";
export { client } from "./generated/client.gen.js";
export * from "./generated/index.js";
export * from "./generated/zod.gen.js";

export interface EdgwayClientOptions {
  /** The admin Worker's origin, e.g. `https://admin.example.com`. */
  adminUrl: string;
  /** Sent with every request: Access service-token or assertion headers. */
  headers?: Record<string, string>;
  /** A fetch to use instead of the global one (e.g. a service binding). */
  fetch?: typeof fetch;
}

/** A client for one admin; pass it as `client` to any SDK function. */
export function createEdgwayClient(options: EdgwayClientOptions): Client {
  // The generated default is the API's mount path (the document's `servers`).
  const base = String(client.getConfig().baseUrl);
  return createClient(
    createConfig({
      baseUrl: new URL(base, options.adminUrl).href,
      headers: options.headers,
      fetch: options.fetch,
    }),
  );
}
